template.css:
.sm-head { display: flex; flex-direction: column; gap: 0.35rem; margin-bottom: -0.4rem; }
.sm-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); }
.sm-ask { font-size: 1.9rem; font-weight: 600; letter-spacing: -0.01em; line-height: 1.15; }

.sm-stage { position: relative; border-radius: var(--radius); overflow: hidden; border: 1px solid var(--border); }
.sm-svg { display: block; width: 100%; height: 480px; touch-action: none; user-select: none; -webkit-user-select: none; cursor: grab; }
.sm-svg.panning { cursor: grabbing; }
.sm-svg.done { cursor: default; }
.sm-svg:focus { outline: none; }
.sm-sea, .sm-lakes path { fill: color-mix(in oklab, var(--foreground) 3%, var(--card, var(--background))); }
.sm-lakes path { stroke: none; pointer-events: none; }

.sm-land path { fill: color-mix(in oklab, var(--foreground) 22%, var(--card, var(--background))); stroke: var(--card, var(--background)); stroke-width: 0.9px; vector-effect: non-scaling-stroke; stroke-linejoin: round; transition: fill 0.12s; }
.sm-land path.other { fill: color-mix(in oklab, var(--foreground) 7%, var(--card, var(--background))); stroke-width: 0.6px; }
[data-tap="1"] .sm-svg:not(.done) .sm-land path:not(.other):not(.picked):hover { fill: color-mix(in oklab, var(--foreground) 34%, var(--card, var(--background))); }
.sm-land path.target { fill: var(--highlight); stroke: color-mix(in oklab, var(--highlight) 60%, var(--foreground)); stroke-width: 1px; }
.sm-land path.picked { fill: var(--highlight); stroke: var(--foreground); stroke-width: 1.2px; }
.sm-land path.right, .sm-land path.answer { fill: var(--success); stroke: color-mix(in oklab, var(--success) 50%, var(--foreground)); stroke-width: 1.2px; }
.sm-land path.wrong { fill: var(--danger); stroke: color-mix(in oklab, var(--danger) 50%, var(--foreground)); stroke-width: 1.2px; }

.sm-dots .dot { fill: color-mix(in oklab, var(--foreground) 32%, transparent); stroke: var(--card, var(--background)); stroke-width: 1px; vector-effect: non-scaling-stroke; }
.sm-dots .dot.hot { fill: var(--highlight); stroke: var(--foreground); }
.sm-dots .dot.right, .sm-dots .dot.answer { fill: var(--success); }
.sm-dots .dot.wrong { fill: var(--danger); }
.sm-marks .ring { fill: none; stroke: var(--highlight); stroke-width: 1.6px; vector-effect: non-scaling-stroke; stroke-dasharray: 3 3; }
[data-mode="result"] .sm-marks .ring { stroke: var(--success); stroke-dasharray: none; stroke-width: 2px; }
[data-mode="result"] .sm-marks .ring.wrong { stroke: var(--danger); }
.sm-marks .cap { fill: var(--card, var(--background)); stroke: var(--foreground); stroke-width: 2px; vector-effect: non-scaling-stroke; }
.sm-marks .cap.wrong { stroke: var(--danger); }
.sm-marks .lbl { font-family: var(--font-sans); font-weight: 600; fill: var(--foreground); paint-order: stroke; stroke: color-mix(in oklab, var(--card, var(--background)) 92%, transparent); stroke-width: 4px; vector-effect: non-scaling-stroke; stroke-linejoin: round; pointer-events: none; }
.sm-marks .lbl.wrong { font-weight: 500; }
.sm-marks .lbl.city { font-weight: 500; font-style: italic; }

.sm-zoom { position: absolute; right: 0.5rem; top: 0.5rem; display: flex; flex-direction: column; gap: 0.3rem; }
.sm-zoom button { width: 2.25rem; height: 2.25rem; border-radius: calc(var(--radius) - 2px); border: 1px solid var(--border); background: color-mix(in oklab, var(--card, var(--background)) 88%, transparent); color: var(--foreground); font: 600 1rem/1 var(--font-sans); cursor: pointer; display: grid; place-items: center; padding: 0; }
.sm-zoom button:hover { background: var(--secondary); }
.sm-zoom button:focus { outline: none; }
.sm-zoom button:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }

.sm-input { font-size: 1.1rem; }
.sm-input.is-close { border-color: var(--warning); }
.sm-status { margin: -0.5rem 0 0; font-size: 0.95rem; color: var(--muted-foreground); }
.sm-hint { margin: -0.7rem 0 0; font-size: 0.8rem; color: var(--muted-foreground); }
.sm-name { font-size: 1.5rem; font-weight: 600; letter-spacing: -0.01em; }
.sm-line { display: inline-flex; align-items: baseline; flex-wrap: wrap; gap: 0 0.6rem; }
.sm-ipa { font-size: 0.9rem; }
.sm-play { align-self: center; width: 1.75rem; height: 1.75rem; border-radius: 999px; border: 1px solid var(--border); background: var(--secondary); color: var(--foreground); font-size: 0.65rem; line-height: 1; padding: 0 0 0 0.12rem; cursor: pointer; display: inline-grid; place-items: center; }
.sm-play:hover { background: color-mix(in oklab, var(--foreground) 14%, var(--secondary)); }
.sm-play:focus { outline: none; }
.sm-play:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }
.sm-official { color: var(--muted-foreground); margin-top: -0.6rem; }
.sm-facts { display: flex; flex-wrap: wrap; gap: 0.4rem 1.4rem; font-size: 0.95rem; }
.sm-facts .e-label { margin-right: 0.35rem; }
@media (max-width: 480px) { .sm-ask { font-size: 1.6rem; } .sm-zoom button { width: 2.75rem; height: 2.75rem; } }

.sm-land path { fill-rule: evenodd; }

[data-face="capital-of"][data-mode="answer"] .sm-hint { display: none; }

template.js:
// Unlabelled geometry is loaded as a type asset; names are revealed only after answering.
const { view } = etude;
const MAP = await (await fetch(etude.asset(view.mapAsset))).json();
const NS = "http://www.w3.org/2000/svg";
const svg = etude.$(".sm-svg");
const stage = etude.$(".sm-stage");
const gLand = etude.$(".sm-land");
const gLakes = etude.$(".sm-lakes");
const gDots = etude.$(".sm-dots");
const gMarks = etude.$(".sm-marks");
const tapFace = !!view.tapFace;
document.body.dataset.face = view.face;
document.body.dataset.tap = tapFace ? "1" : "0";
const svgEl = (tag, attrs = {}) => {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
  return n;
};

// ---------- draw ----------
const paths = [];
const centers = [];
const boxes = [];
const ringsD = (rings, box) => {
  let d = "";
  for (const ring of rings) {
    let x = ring[0], y = ring[1];
    d += `M${x} ${y}`;
    for (let j = 2; j < ring.length; j += 2) {
      x += ring[j];
      y += ring[j + 1];
      if (box) {
        if (x < box[0]) box[0] = x;
        if (y < box[1]) box[1] = y;
        if (x > box[2]) box[2] = x;
        if (y > box[3]) box[3] = y;
      }
      d += `l${ring[j]} ${ring[j + 1]}`;
    }
    d += "Z";
  }
  return d;
};
MAP.f.forEach((f, i) => {
  const [playable, , cx, cy] = f;
  centers[i] = [cx, cy];
  const box = [Infinity, Infinity, -Infinity, -Infinity];
  const p = svgEl("path", { d: ringsD(f.slice(4), box), class: playable ? "s" : "other" });
  boxes[i] = box;
  p.dataset.i = i;
  paths[i] = p;
});
// Neighbouring countries first, so the states' outlines sit on top.
for (const i of paths.keys()) if (!MAP.f[i][0]) gLand.append(paths[i]);
for (const i of paths.keys()) if (MAP.f[i][0]) gLand.append(paths[i]);
for (const ring of MAP.lakes) gLakes.append(svgEl("path", { d: ringsD([ring]) }));
MAP.f.forEach(([playable, tiny, cx, cy], i) => {
  if (!playable || !tiny) return;
  const dot = svgEl("circle", { cx, cy, r: 1, class: "dot" });
  dot.dataset.i = i;
  gDots.append(dot);
});

// ---------- framing, zoom and pan ----------
let vb = [0, 0, 1, 1];
let home = [0, 0, 1, 1];
// The map's height is set below, so its aspect is measured, not assumed.
const measure = () => {
  const r = svg.getBoundingClientRect();
  return r.width > 0 && r.height > 0 ? r.height / r.width : 0.8;
};
let ASPECT = measure();
const fit = ([x, y, w, h], pad = 0.04) => {
  const pw = w * (1 + 2 * pad), ph = h * (1 + 2 * pad);
  const W2 = Math.max(pw, ph / ASPECT), H2 = W2 * ASPECT;
  return [x + w / 2 - W2 / 2, y + h / 2 - H2 / 2, W2, H2];
};
// Germany is taller than it is wide: phones get a tall map, wider screens a capped one.
const sizeStage = () => {
  const w = stage.getBoundingClientRect().width || 600;
  const ratio = Math.min(1.2, Math.max(0.58, MAP.home[3] / MAP.home[2]));
  svg.style.height = Math.round(w < 520 ? w * ratio : Math.min(Math.max(w * ratio, 340), 540)) + "px";
};
sizeStage();
ASPECT = measure();
home = frameHome();
function frameHome() {
  const full = fit(MAP.home);
  if (view.target == null) return full;
  const [x0,y0,x1,y1] = boxes[view.target];
  if (x1-x0 < full[2]*.18 && y1-y0 < full[3]*.18) {
    const width = Math.max(full[2]/3.2, (x1-x0)*3, (y1-y0)*3/ASPECT);
    return fit([(x0+x1-width)/2, (y0+y1-width*ASPECT)/2, width, width*ASPECT], 0);
  }
  return full;
}
const pxPerUnit = () => (svg.getBoundingClientRect().width || 600) / vb[2];
const [bx0, by0, bx1, by1] = MAP.bounds;
const clampVb = () => {
  // The map is cut out of a larger one; never show past its edges, and stop at about 50 km across.
  const maxW = Math.max(home[2], Math.min(bx1 - bx0, (by1 - by0) / ASPECT));
  const w = Math.min(Math.max(vb[2], 500), maxW);
  if (w !== vb[2]) vb = [vb[0] + (vb[2] - w) / 2, vb[1] + (vb[3] - w * ASPECT) / 2, w, w * ASPECT];
  const pin = (v, lo, hi, size) => (size >= hi - lo ? (lo + hi - size) / 2 : Math.min(Math.max(v, lo), hi - size));
  vb = [pin(vb[0], bx0, bx1, vb[2]), pin(vb[1], by0, by1, vb[3]), vb[2], vb[3]];
};

// Labels keep a fixed size on screen. State names move up or down when they'd cover a capital,
// a ring or another name.
const textBox = (t, x, y, u) => {
  const w = t.textContent.length * 13 * 0.6 * u, h = 15 * u;
  const anchor = t.getAttribute("text-anchor");
  const x0 = anchor === "start" ? x : x - w / 2;
  return [x0, y - h * 0.8, x0 + w, y + h * 0.2];
};
const overlaps = (a, b) => a[0] < b[2] && b[0] < a[2] && a[1] < b[3] && b[1] < a[3];
function layoutLabels(u) {
  const fixed = [];
  for (const c of gMarks.querySelectorAll("circle")) {
    const x = Number(c.getAttribute("cx")), y = Number(c.getAttribute("cy")), r = Number(c.getAttribute("r"));
    fixed.push([x - r, y - r, x + r, y + r]);
  }
  for (const t of gMarks.querySelectorAll("text.city")) {
    const [x, y] = [Number(t.dataset.x) + 9 * u, Number(t.dataset.y) + 4.5 * u];
    t.setAttribute("x", x);
    t.setAttribute("y", y);
    t.setAttribute("font-size", 12 * u);
    fixed.push(textBox(t, x, y, u));
  }
  for (const t of gMarks.querySelectorAll("text.state")) {
    const x = Number(t.dataset.x), y0 = Number(t.dataset.y) + 4.5 * u;
    t.setAttribute("font-size", 13 * u);
    let best = y0;
    for (const dy of [0, -20, 20, -38, 38, -56, 56]) {
      const y = y0 + dy * u;
      if (!fixed.some((b) => overlaps(b, textBox(t, x, y, u)))) {
        best = y;
        break;
      }
    }
    t.setAttribute("x", x);
    t.setAttribute("y", best);
    fixed.push(textBox(t, x, best, u));
  }
}
function apply() {
  svg.setAttribute("viewBox", vb.map((v) => v.toFixed(1)).join(" "));
  const u = 1 / pxPerUnit();
  for (const c of gDots.children) c.setAttribute("r", (c.classList.contains("hot") ? 7 : 4.5) * u);
  for (const c of gMarks.querySelectorAll("circle.ring")) c.setAttribute("r", 15 * u);
  for (const c of gMarks.querySelectorAll("circle.cap")) c.setAttribute("r", 4 * u);
  layoutLabels(u);
}
const zoomAt = (k, sx, sy) => {
  // sx, sy: point in [0,1] of the stage that stays put
  const nw = vb[2] / k, nh = vb[3] / k;
  vb = [vb[0] + (vb[2] - nw) * sx, vb[1] + (vb[3] - nh) * sy, nw, nh];
  clampVb();
  apply();
};
const toMap = (e) => {
  const r = svg.getBoundingClientRect();
  return [vb[0] + ((e.clientX - r.left) / r.width) * vb[2], vb[1] + ((e.clientY - r.top) / r.height) * vb[3], (e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height];
};
svg.addEventListener("wheel", (e) => {
  e.preventDefault();
  const [, , sx, sy] = toMap(e);
  zoomAt(Math.exp(-e.deltaY * (e.ctrlKey ? 0.01 : 0.0022)), sx, sy);
}, { passive: false });
etude.$(".sm-in").addEventListener("click", () => zoomAt(1.6, 0.5, 0.5));
etude.$(".sm-out").addEventListener("click", () => zoomAt(1 / 1.6, 0.5, 0.5));
etude.$(".sm-home").addEventListener("click", () => { vb = home.slice(); apply(); });

const pointers = new Map();
let gesture = null;
svg.addEventListener("pointerdown", (e) => {
  svg.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  gesture = { moved: pointers.size > 1, start: { x: e.clientX, y: e.clientY }, vb: vb.slice(), dist: null };
  if (pointers.size === 2) {
    const [a, b] = [...pointers.values()];
    gesture.dist = Math.hypot(a.x - b.x, a.y - b.y);
    gesture.mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
  }
});
svg.addEventListener("pointermove", (e) => {
  if (!pointers.has(e.pointerId) || !gesture) return;
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  const r = svg.getBoundingClientRect();
  if (pointers.size === 2 && gesture.dist) {
    const [a, b] = [...pointers.values()];
    const k = Math.hypot(a.x - b.x, a.y - b.y) / gesture.dist;
    const sx = (gesture.mid.x - r.left) / r.width, sy = (gesture.mid.y - r.top) / r.height;
    const nw = gesture.vb[2] / k, nh = gesture.vb[3] / k;
    vb = [gesture.vb[0] + (gesture.vb[2] - nw) * sx, gesture.vb[1] + (gesture.vb[3] - nh) * sy, nw, nh];
    clampVb();
    apply();
    return;
  }
  const dx = e.clientX - gesture.start.x, dy = e.clientY - gesture.start.y;
  if (!gesture.moved && Math.hypot(dx, dy) < 6) return;
  gesture.moved = true;
  svg.classList.add("panning");
  vb = [gesture.vb[0] - (dx / r.width) * gesture.vb[2], gesture.vb[1] - (dy / r.height) * gesture.vb[3], vb[2], vb[3]];
  clampVb();
  apply();
});
const release = (e) => {
  if (!pointers.has(e.pointerId)) return;
  pointers.delete(e.pointerId);
  svg.classList.remove("panning");
  if (gesture && !gesture.moved && pointers.size === 0) tap(e);
  if (pointers.size === 0) gesture = null;
};
svg.addEventListener("pointerup", release);
svg.addEventListener("pointercancel", (e) => { pointers.delete(e.pointerId); gesture = null; svg.classList.remove("panning"); });

// ---------- picking ----------
let pick = null;
const pt = svg.createSVGPoint();
function hit(e) {
  const order = [...gLand.children].map((p) => Number(p.dataset.i));
  const [mx, my] = toMap(e);
  // A tap right on Bremen's dot picks it. Otherwise the state under the finger wins, and a near
  // miss goes to the dot.
  const ppu = pxPerUnit();
  let best = null, bestD = Infinity;
  for (const c of gDots.children) {
    const i = Number(c.dataset.i);
    const d = Math.hypot(centers[i][0] - mx, centers[i][1] - my) * ppu;
    if (d < bestD) (best = i), (bestD = d);
  }
  if (best != null && bestD <= 5.5) return best;
  pt.x = mx;
  pt.y = my;
  for (let k = order.length - 1; k >= 0; k--) {
    const i = order[k];
    if (!MAP.f[i][0]) continue;
    const b = boxes[i];
    if (mx < b[0] || mx > b[2] || my < b[1] || my > b[3]) continue;
    if (paths[i].isPointInFill(pt)) return i;
  }
  return best != null && bestD <= 14 ? best : null;
}
function setPick(i) {
  if (pick != null) {
    paths[pick].classList.remove("picked");
    gDots.querySelector(`[data-i="${pick}"]`)?.classList.remove("hot");
  }
  pick = i;
  if (pick != null) {
    paths[pick].classList.add("picked");
    gLand.append(paths[pick]); // draw on top so the outline isn't covered by neighbours
    gDots.querySelector(`[data-i="${pick}"]`)?.classList.add("hot");
  }
  etude.$(".sm-status").textContent = pick == null ? `Tap a ${view.unitLabel}` : "Selected. Check when you're sure, or tap another.";
  etude.setReady(pick != null);
  apply();
}
function tap(e) {
  if (!tapFace || etude.mode !== "answer") return;
  const i = hit(e);
  if (i != null) setPick(i === pick ? null : i);
}

// ---------- face setup ----------
const ring = (i, cls = "") => gMarks.append(svgEl("circle", { cx: centers[i][0], cy: centers[i][1], r: 1, class: ("ring " + cls).trim() }));
const input = etude.$(".sm-input");
if (tapFace) {
  etude.setReady(false);
  if (etude.answer && Number.isInteger(etude.answer.pick)) setPick(etude.answer.pick);
  etude.getAnswer(() => ({ pick }));
} else {
  const t = view.target;
  if (t != null) {
    paths[t].classList.add("target");
    gLand.append(paths[t]);
    gDots.querySelector(`[data-i="${t}"]`)?.classList.add("hot", "target");
    if (MAP.f[t][1]) ring(t);
  }
  etude.setReady(false);
  if (typeof etude.answer === "string") input.value = etude.answer;
  input.addEventListener("input", () => etude.setReady(input.value.trim().length > 0));
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (input.value.trim()) etude.submit();
    }
  });
  etude.setReady(input.value.trim().length > 0);
  etude.getAnswer(() => input.value);
}
window.addEventListener("keydown", (e) => {
  if (tapFace && e.key === "Enter" && pick != null && etude.mode === "answer") {
    e.preventDefault();
    etude.submit();
  }
});

vb = home.slice();
clampVb();
apply();
// Keep the centre and width when the card resizes; refit the home view to the new shape.
new ResizeObserver(() => {
  sizeStage();
  const a = measure();
  if (Math.abs(a - ASPECT) > 0.002) {
    const atHome = vb.every((v, i) => Math.abs(v - home[i]) < 1e-6);
    ASPECT = a;
    home = frameHome();
    if (atHome) vb = home.slice();
    else {
      const cy = vb[1] + vb[3] / 2;
      vb = [vb[0], cy - (vb[2] * a) / 2, vb[2], vb[2] * a];
    }
    clampVb();
  }
  apply();
}).observe(stage);

// ---------- result ----------
// An audio field is the name of a file shipped with the type, or a /media/ path (audio pasted into the item).
const audioUrl = (name) => (/^(\/|https?:\/\/)/.test(name) ? name : etude.asset(name));
const play = (name) => {
  if (!name) return;
  try {
    new Audio(audioUrl(name)).play().catch(() => {});
  } catch (e) {
    console.warn("audio:", e.message);
  }
};
etude.root.addEventListener("click", (e) => {
  const b = e.target.closest(".sm-play");
  if (b) play(b.dataset.audio);
});
const label = (x, y, text, cls) => {
  const t = svgEl("text", { class: "lbl " + cls, "text-anchor": cls.includes("city") ? "start" : "middle" });
  t.textContent = text;
  t.dataset.x = x;
  t.dataset.y = y;
  gMarks.append(t);
};
etude.onResult(({ grade, key }) => {
  svg.classList.add("done");
  if (input) input.disabled = true;
  const t = key.index;
  const d = grade?.details ?? {};
  const score = grade?.score ?? 0;
  const right = tapFace ? pick === t : score >= 0.9;
  paths[t].classList.remove("target");
  paths[t].classList.add(right ? "right" : "answer");
  gLand.append(paths[t]);
  gDots.querySelector(`[data-i="${t}"]`)?.classList.add("hot", right ? "right" : "answer");
  if (input) input.classList.add(score >= 1 ? "is-correct" : score >= 0.9 ? "is-close" : "is-wrong");
  const other = tapFace ? (pick != null && pick !== t ? pick : null) : Number.isInteger(d.otherIndex) && d.otherIndex !== t ? d.otherIndex : null;
  if (MAP.f[t][1] && other == null) ring(t);
  if (other != null) {
    paths[other].classList.add("wrong");
    gLand.append(paths[other]);
    gDots.querySelector(`[data-i="${other}"]`)?.classList.add("wrong");
    if (MAP.f[other][1]) ring(other, "wrong");
    if (MAP.f[t][1]) ring(t);
    gLand.append(paths[t]); // the answer stays on top, so an enclave like Bremen shows
  }
  if (!key.cityState) {
    [MAP.caps[t], ...(MAP.extraCaps[t] || [])].forEach(([x,y], i) => {
      gMarks.append(svgEl("circle", { cx: x, cy: y, r: 1, class: "cap" }));
      label(x, y, key.capitalChoices[i], "city");
    });
  }
  label(centers[t][0], centers[t][1], key.state, "state answer");
  if (other != null && d.otherName) label(centers[other][0], centers[other][1], d.otherName, "state wrong");
  // A wrong answer is shown on the whole map, so both states are in view.
  if (other != null) {
    vb = fit(MAP.home);
    clampVb();
  }
  apply();
  // Say what the card was about, unless the answer is only being peeked at.
  if (etude.mode !== "preview") play(view.face === "capital" ? key.capital_audio : key.state_audio);
});
